import json
items=json.load(open('examples_part1.json'))
def add(id,topic,grade,diff,q,ans,sol,opts):
    items.append(dict(id=id,knowledgeTitle=topic,grade=grade,difficulty=diff,type='choice',
        question=q,options=opts,answer=ans,solution=sol,source='local'))
G8='初二'
add('EX_G8_POWMUL_01','同底数幂乘法',G8,1,r'计算：$a^2\cdot a^3$',r'$a^5$',r'同底数幂相乘，底数不变，指数相加：$a^{2+3}=a^5$。',[r'$a^5$',r'$a^6$',r'$a^8$',r'$2a^5$'])
add('EX_G8_POWMUL_02','同底数幂乘法',G8,2,r'计算：$x^4\cdot x$',r'$x^5$',r'$x$ 的指数是 $1$，$x^{4+1}=x^5$。',[r'$x^5$',r'$x^4$',r'$x^8$',r'$2x^4$'])
add('EX_G8_POWMUL_03','同底数幂乘法',G8,3,r'计算：$(-a)^2\cdot a^3$',r'$a^5$',r'$(-a)^2=a^2$，再与 $a^3$ 相乘得 $a^5$。',[r'$a^5$',r'$-a^5$',r'$a^6$',r'$-a^6$'])
add('EX_G8_POWPOW_01','幂的乘方',G8,1,r'计算：$(a^2)^3$',r'$a^6$',r'幂的乘方，底数不变，指数相乘：$a^{2\times3}=a^6$。',[r'$a^6$',r'$a^5$',r'$a^8$',r'$a^9$'])
add('EX_G8_POWPOW_02','幂的乘方',G8,2,r'计算：$(x^3)^4$',r'$x^{12}$',r'$x^{3\times4}=x^{12}$。',[r'$x^{12}$',r'$x^7$',r'$x^{64}$',r'$x^{9}$'])
add('EX_G8_POWPOW_03','幂的乘方',G8,3,r'计算：$(-a^2)^3$',r'$-a^6$',r'$a^2$ 先乘方得 $a^6$，外面的负号保留：$-a^6$。',[r'$-a^6$',r'$a^6$',r'$-a^5$',r'$a^5$'])
add('EX_G8_PRODPOW_01','积的乘方',G8,1,r'计算：$(2x)^3$',r'$8x^3$',r'每个因式分别乘方：$2^3\cdot x^3=8x^3$。',[r'$8x^3$',r'$2x^3$',r'$6x^3$',r'$8x$'])
add('EX_G8_PRODPOW_02','积的乘方',G8,2,r'计算：$(-3a^2)^2$',r'$9a^4$',r'$(-3)^2=9$，$(a^2)^2=a^4$，所以是 $9a^4$。',[r'$9a^4$',r'$-9a^4$',r'$6a^4$',r'$9a^2$'])
add('EX_G8_PRODPOW_03','积的乘方',G8,3,r'计算：$(ab^2)^3$',r'$a^3b^6$',r'$a^3\cdot (b^2)^3=a^3b^6$。',[r'$a^3b^6$',r'$a^3b^2$',r'$ab^6$',r'$a^3b^8$'])
add('EX_G8_SQDIFF_01','平方差公式',G8,1,r'计算：$(x+3)(x-3)$',r'$x^2-9$',r'平方差公式：$(a+b)(a-b)=a^2-b^2$，所以是 $x^2-9$。',[r'$x^2-9$',r'$x^2+9$',r'$x^2-6x+9$',r'$x^2-3$'])
add('EX_G8_SQDIFF_02','平方差公式',G8,2,r'计算：$(2a+b)(2a-b)$',r'$4a^2-b^2$',r'$(2a)^2-b^2=4a^2-b^2$。',[r'$4a^2-b^2$',r'$2a^2-b^2$',r'$4a^2+b^2$',r'$4a^2-4ab+b^2$'])
add('EX_G8_SQDIFF_03','平方差公式',G8,3,r'计算：$101\times99$',r'$9999$',r'写成 $(100+1)(100-1)=100^2-1=9999$。',[r'$9999$',r'$10000$',r'$9998$',r'$10100$'])
add('EX_G8_SQSUM_01','完全平方公式',G8,1,r'计算：$(x+2)^2$',r'$x^2+4x+4$',r'$(a+b)^2=a^2+2ab+b^2$，所以是 $x^2+4x+4$。',[r'$x^2+4x+4$',r'$x^2+4$',r'$x^2+2x+4$',r'$x^2-4x+4$'])
add('EX_G8_SQSUM_02','完全平方公式',G8,2,r'计算：$(3a-1)^2$',r'$9a^2-6a+1$',r'$(a-b)^2=a^2-2ab+b^2$：$9a^2-6a+1$。',[r'$9a^2-6a+1$',r'$9a^2+6a+1$',r'$9a^2-1$',r'$3a^2-6a+1$'])
add('EX_G8_SQSUM_03','完全平方公式',G8,3,r'计算：$(x-2y)^2$',r'$x^2-4xy+4y^2$',r'$x^2-2\cdot x\cdot2y+(2y)^2=x^2-4xy+4y^2$。',[r'$x^2-4xy+4y^2$',r'$x^2+4xy+4y^2$',r'$x^2-4y^2$',r'$x^2-2xy+4y^2$'])
add('EX_G8_GCF_01','提公因式法',G8,1,r'分解因式：$6x^2+9x$',r'$3x(2x+3)$',r'公因式是 $3x$，提取后得 $3x(2x+3)$。',[r'$3x(2x+3)$',r'$3(2x^2+3x)$',r'$x(6x+9)$',r'$3x(2x+9)$'])
add('EX_G8_GCF_02','提公因式法',G8,2,r'分解因式：$4a^3b-8a^2b^2$',r'$4a^2b(a-2b)$',r'公因式是 $4a^2b$，提取后得 $4a^2b(a-2b)$。',[r'$4a^2b(a-2b)$',r'$4a^2b(a-2)$',r'$2a^2b(2a-4b)$',r'$4ab(a^2-2ab)$'])
add('EX_G8_GCF_03','提公因式法',G8,3,r'分解因式：$-3x^2+6x$',r'$-3x(x-2)$',r'先提 $-3x$：$-3x(x-2)$。',[r'$-3x(x-2)$',r'$3x(x-2)$',r'$-3x(x+2)$',r'$-x(3x-6)$'])
add('EX_G8_CROSS_01','十字相乘法',G8,1,r'分解因式：$x^2+5x+6$',r'$(x+2)(x+3)$',r'找两数积为 $6$、和为 $5$：$2$ 和 $3$，所以是 $(x+2)(x+3)$。',[r'$(x+2)(x+3)$',r'$(x-2)(x-3)$',r'$(x+1)(x+6)$',r'$(x+2)(x-3)$'])
add('EX_G8_CROSS_02','十字相乘法',G8,2,r'分解因式：$x^2-7x+12$',r'$(x-3)(x-4)$',r'找两数积为 $12$、和为 $-7$：$-3$ 和 $-4$。',[r'$(x-3)(x-4)$',r'$(x+3)(x+4)$',r'$(x-2)(x-6)$',r'$(x-1)(x-12)$'])
add('EX_G8_CROSS_03','十字相乘法',G8,3,r'分解因式：$2x^2+5x+3$',r'$(2x+3)(x+1)$',r'十字相乘：$2x\cdot1+3\cdot x=5x$，所以是 $(2x+3)(x+1)$。',[r'$(2x+3)(x+1)$',r'$(2x+1)(x+3)$',r'$(2x-3)(x-1)$',r'$(x+3)(2x+1)$'])
add('EX_G8_RAD_01','二次根式乘除',G8,1,r'计算：$\sqrt{2}\cdot\sqrt{8}$',r'$4$',r'$\sqrt{2}\cdot\sqrt{8}=\sqrt{16}=4$。',[r'$4$',r'$2$',r'$8$',r'$16$'])
add('EX_G8_RAD_02','二次根式乘除',G8,2,r'计算：$\sqrt{12}\div\sqrt{3}$',r'$2$',r'$\sqrt{12}\div\sqrt{3}=\sqrt{4}=2$。',[r'$2$',r'$4$',r'$\sqrt{3}$',r'$6$'])
add('EX_G8_RAD_03','二次根式乘除',G8,3,r'计算：$\sqrt{18}\cdot\sqrt{2}$',r'$6$',r'$\sqrt{18}\cdot\sqrt{2}=\sqrt{36}=6$。',[r'$6$',r'$3$',r'$9$',r'$36$'])
json.dump(items,open('app/src/main/assets/examples.json','w',encoding='utf-8'),ensure_ascii=False,indent=2)
print('total',len(items),'topics',len({x['knowledgeTitle'] for x in items}))
